// Local administrative backup APIs are deliberately not registered as HTTP
// operations. Possession of the separately stored recovery key is required.
import (
	"context"
	"crypto/aes"
	"crypto/cipher"
	"crypto/hmac"
	"crypto/rand"
	"crypto/sha256"
	"database/sql"
	"encoding/hex"
	"encoding/json"
	"fmt"
