func upgradeConfigurationTemplate(ctx context.Context, sqls [][]byte, contracts *Contracts) (string, string, error) {
	if len(sqls) != 24 {
		return "", "", fmt.Errorf("UPGRADE_PLAN_UNSUPPORTED")
	}
	stage, e := os.MkdirTemp("", ".researchos-configuration-template-")
	if e != nil {
		return "", "", e
	}
	defer backupDiscard(stage)
	db, e := store.Open(filepath.Join(stage, "schema.sqlite"))
	if e != nil {
		return "", "", e
	}
	defer db.Close()
	for i, raw := range sqls[:22] {
		if _, e = db.ExecContext(ctx, string(raw)); e != nil {
			return "", "", e
		}
		if _, e = db.ExecContext(ctx, "INSERT INTO schema_migrations(version) VALUES(?)", i+1); e != nil {
			return "", "", e
		}
	}
	if _, e = db.ExecContext(ctx, string(sqls[23])); e != nil {
		return "", "", e
	}
	if e = installClientSessionFence(ctx, db, false); e != nil {
		return "", "", e
	}
	before, e := backupSchema(db)
	if e != nil {
		return "", "", e
	}
	if _, e = (&Service{DB: db, Contracts: contracts}).backupFence(ctx); e != nil {
		return "", "", e
	}
	if e = upgradeConfigurationMigration(ctx, db, sqls[22]); e != nil {
		return "", "", e
	}
	after, e := backupSchema(db)
	return before, after, e
}

func upgradePreparedAbandonmentBackup(ctx context.Context, handoff PreparedBackupHandoffOptions, verifier upgradeVerifier) (report RestoreReport, err error) {
    opt := handoff.Upgrade
    report = RestoreReport{Started: Now(), Status: "FAILED"}
    if opt.Plan != PreparedAbandonmentSchemaUpgradePlan { return report, fmt.Errorf("PREPARED_UPGRADE_PLAN_UNSUPPORTED") }
    if err := preparedHandoffPaths(&opt, &handoff); err != nil { return report, err }
    lease, err := acquirePreparedUpgradeRootLease(filepath.Dir(opt.Source))
    if err != nil { return report, err }
    defer func() {
        if closeErr := lease.Close(); closeErr != nil && err == nil { err = closeErr }
    }()
    sourceRelease, _, err := preparedUpgradeRelease(opt.SourceRoot, 23)
    if err != nil { return report, err }
    targetRelease, sqls, err := preparedUpgradeRelease(opt.TargetRoot, 24)
    if err != nil { return report, err }
    sourceProgram, targetProgram, err := preparedUpgradeProgramHashes(opt, true)
    if err != nil { return report, err }
