    if err != nil { return report, err }
    contracts, err := LoadContracts(filepath.Join(opt.TargetRoot, "spec/v2.0/contracts"))
    if err != nil { return report, err }
    schemas, err := preparedUpgradeTemplate(ctx, sqls, contracts)
